/* ============================================
   RATING COMPONENT
   Star-scale rating control
   ============================================ */

@layer rift.tokens, rift.preset, rift.components;

@layer rift.components {

.ds-rating {
  display: inline-flex;
  align-items: center;
  gap: var(--gap-050);
}

/* ============================================
   STEPS
   ============================================ */

.ds-rating__step {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0;
  border: none;
  background: none;
  cursor: pointer;
  color: var(--color-icon-secondary);
  border-radius: var(--radius-100);
  transition: color var(--motion-duration-fast) var(--motion-ease-standard),
    transform var(--motion-duration-fast) var(--motion-ease-standard);
}

.ds-rating__icon {
  --icon-size: var(--icon-size-600);
}

.ds-rating--compact .ds-rating__icon {
  --icon-size: var(--icon-size-500);
}

.ds-rating__step--filled {
  color: var(--color-core-accent-gold);
}

.ds-rating__step--filled .ds-rating__icon {
  --material-symbols-fill: 1;
}

/* ============================================
   STATES
   ============================================ */

.ds-rating__step:hover {
  transform: scale(1.1);
}

.ds-rating__step:focus-visible {
  outline: 2px solid var(--color-action-primary-bg);
  outline-offset: 2px;
}

.ds-rating--read-only .ds-rating__step {
  cursor: default;
}

.ds-rating--read-only .ds-rating__step:hover {
  transform: none;
}

.ds-rating--disabled .ds-rating__step {
  opacity: 0.4;
  cursor: not-allowed;
}

.ds-rating--disabled .ds-rating__step:hover {
  transform: none;
}

/* ============================================
   THUMBS (variant="thumbs")
   A two-way verdict: the chosen thumb fills in the primary
   icon colour (a verdict, not a score, so not the star gold),
   and each thumb sits in a tertiary icon button's round hover.
   ============================================ */

.ds-rating--thumbs {
  gap: var(--gap-100);
}

.ds-rating--thumbs .ds-rating__step {
  justify-content: center;
  width: var(--control-height-compact);
  height: var(--control-height-compact);
  border-radius: var(--radius-pill);
}

.ds-rating--thumbs .ds-rating__step:not(:disabled):hover {
  background-color: var(--color-action-passive-bg-hover);
}

.ds-rating--thumbs .ds-rating__step--filled {
  color: var(--color-icon-primary);
}

} /* @layer rift.components */

'use client';

import React, { useState } from 'react';
import './Rating.css';
import '../../fonts/material-symbols.css';
import { logicalArrowKey, mirrorClass } from '../../behaviors/direction';

/** Props owned by Rating itself — everything else falls through to the root node. */
type RatingOwnProps = {
  /** Current rating (controlled). 0 means no rating. */
  value?: number;
  /** Initial rating for uncontrolled use. 0 means no rating. */
  defaultValue?: number;
  /** Number of steps on the scale */
  max?: number;
  /**
   * Convenience callback receiving the new rating directly.
   * Fires on every selection, including a clear back to 0 via `allowClear`.
   */
  onValueChange?: (value: number) => void;
  /** Display-only mode — renders the current rating with no interaction */
  readOnly?: boolean;
  /** Whether the control is disabled */
  disabled?: boolean;
  /** Selecting the already-selected step clears the rating back to 0 */
  allowClear?: boolean;
  /** Glyph drawn for each step — Material Symbol name (string) or custom element (ReactNode). A string glyph solidifies on filled steps via the font's fill axis; a custom element should draw with `currentColor` so the filled colour still reads. */
  icon?: string | React.ReactNode;
  /** Component size */
  size?: 'default' | 'compact';
  /** Accessible name for the group, and the base of each step's label (in the `thumbs` form the group's name only; each thumb is named by `upLabel` or `downLabel`) */
  label?: string;
  /**
   * The spoken value, given a step (or, in `readOnly` mode, the current
   * rating) and `max`. Defaults to "3 out of 5". It follows `label` and a
   * colon, as in "Rating: 3 out of 5".
   */
  valueLabel?: (value: number, max: number) => string;
  /** Additional CSS classes */
  className?: string;
  /**
   * The scale's form. `stars` (the default) is a row of `max` steps that
   * fill up to the value. `thumbs` is a two-way verdict, a thumb up and a
   * thumb down, for a quick "Was this helpful?": value 1 is up, 2 is down,
   * 0 is no answer yet, and `max`, `icon` and `valueLabel` are ignored.
   */
  variant?: 'stars' | 'thumbs';
  /** Accessible name of the thumb up in the `thumbs` form. */
  upLabel?: string;
  /** Accessible name of the thumb down in the `thumbs` form. */
  downLabel?: string;
};

export interface RatingProps
  extends RatingOwnProps,
    Omit<React.ComponentPropsWithoutRef<'div'>, keyof RatingOwnProps> {}

const defaultValueLabel = (value: number, max: number) => `${value} out of ${max}`;

/**
 * Rating control: a star scale, or with `variant="thumbs"` a thumb up and a
 * thumb down for a quick "Was this helpful?". Behaves as a radio group:
 * each step is a `role="radio"` button, arrow keys move the selection, and
 * the current step holds the roving tab stop. `readOnly` renders the same
 * row as a static image with a spoken label ("N out of M", or the thumb's
 * label).
 *
 * Forwards a ref to the root element and spreads unrecognised props onto it.
 */
export const Rating = React.forwardRef<HTMLDivElement, RatingProps>(
  (
    {
      variant = 'stars',
      upLabel = 'Yes',
      downLabel = 'No',
      value,
      defaultValue = 0,
      max: maxProp = 5,
      onValueChange,
      readOnly = false,
      disabled = false,
      allowClear = false,
      icon = 'star',
      size = 'default',
      label = 'Rating',
      valueLabel = defaultValueLabel,
      className = '',
      ...rest
    },
    ref,
  ) => {
    const thumbs = variant === 'thumbs';
    const max = thumbs ? 2 : maxProp;
    const [internalValue, setInternalValue] = useState(defaultValue);
    const [hoverValue, setHoverValue] = useState(0);

    const baseClass = 'ds-rating';
    const currentValue = value ?? internalValue;
    // Hover previews the would-be selection; keyboard and touch see the real value.
    const displayValue = !readOnly && !disabled && hoverValue > 0 ? hoverValue : currentValue;

    const classes = [
      baseClass,
      `${baseClass}--${size}`,
      thumbs ? `${baseClass}--thumbs` : '',
      readOnly ? `${baseClass}--read-only` : '',
      disabled ? `${baseClass}--disabled` : '',
      className,
    ]
      .filter(Boolean)
      .join(' ');

    const setValue = (next: number) => {
      const resolved = allowClear && next === currentValue ? 0 : next;
      if (value === undefined) setInternalValue(resolved);
      onValueChange?.(resolved);
    };

    const handleKeyDown = (event: React.KeyboardEvent) => {
      let next: number | null = null;
      switch (logicalArrowKey(event.key, event.currentTarget)) {
        case 'ArrowRight':
        case 'ArrowUp':
          next = Math.min(max, currentValue + 1);
          break;
        case 'ArrowLeft':
        case 'ArrowDown':
          next = Math.max(1, currentValue - 1);
          break;
        case 'Home':
          next = 1;
          break;
        case 'End':
          next = max;
          break;
      }
      if (next !== null) {
        event.preventDefault();
        if (value === undefined) setInternalValue(next);
        onValueChange?.(next);
        // Keep focus on the newly selected step so the roving tab stop follows.
        const steps = event.currentTarget.querySelectorAll<HTMLButtonElement>('[role="radio"]');
        steps[next - 1]?.focus();
      }
    };

    const steps = Array.from({ length: max }, (_, i) => i + 1);
    // Stars fill up to the value; a thumb is either the one chosen or not.
    const isFilled = (step: number) => (thumbs ? step === displayValue : step <= displayValue);
    const iconFor = (step: number) => (thumbs ? (step === 1 ? 'thumb_up' : 'thumb_down') : icon);
    const stepLabel = (step: number) =>
      thumbs ? (step === 1 ? upLabel : downLabel) : valueLabel(step, max);

    if (readOnly) {
      return (
        <div
          {...rest}
          ref={ref}
          className={classes}
          role="img"
          aria-label={
            rest['aria-label'] ??
            (thumbs
              ? currentValue
                ? `${label}: ${stepLabel(currentValue)}`
                : label
              : `${label}: ${valueLabel(currentValue, max)}`)
          }
        >
          {steps.map((step) => (
            <span
              key={step}
              className={`${baseClass}__step ${isFilled(step) ? `${baseClass}__step--filled` : ''}`}
              aria-hidden="true"
            >
              <span className={`${baseClass}__icon${typeof iconFor(step) === 'string' ? ` material-symbols-rounded ${mirrorClass(iconFor(step))}` : ''}`}>{iconFor(step)}</span>
            </span>
          ))}
        </div>
      );
    }

    return (
      <div
        {...rest}
        ref={ref}
        className={classes}
        role="radiogroup"
        aria-label={rest['aria-label'] ?? label}
        aria-disabled={disabled || undefined}
        onKeyDown={disabled ? undefined : handleKeyDown}
        onMouseLeave={() => setHoverValue(0)}
      >
        {steps.map((step) => {
          const checked = step === currentValue;
          // The checked step holds the tab stop; with no rating yet, the first does.
          const tabStop = checked || (currentValue === 0 && step === 1);
          return (
            <button
              key={step}
              type="button"
              role="radio"
              aria-checked={checked}
              aria-label={thumbs ? stepLabel(step) : label ? `${label}: ${stepLabel(step)}` : stepLabel(step)}
              tabIndex={tabStop ? 0 : -1}
              disabled={disabled}
              className={`${baseClass}__step ${isFilled(step) ? `${baseClass}__step--filled` : ''}`}
              onClick={() => setValue(step)}
              onMouseEnter={() => setHoverValue(step)}
            >
              <span className={`${baseClass}__icon${typeof iconFor(step) === 'string' ? ` material-symbols-rounded ${mirrorClass(iconFor(step))}` : ''}`} aria-hidden="true">
                {iconFor(step)}
              </span>
            </button>
          );
        })}
      </div>
    );
  },
);

Rating.displayName = 'Rating';
